cypress_script:
describe('Login Form Tests', () => {
  it('should log in successfully with valid credentials', () => {
    cy.visit('https://practicesoftwaretesting.com/auth/login');
    cy.get('#email').type('test@example.com');
    cy.get('#password').type('password123');
    cy.get('[data-test="login-submit"]').click();
    cy.url().should('not.eq', 'https://practicesoftwaretesting.com/auth/login');
  });

  it('should not log in with empty fields', () => {
    cy.visit('https://practicesoftwaretesting.com/auth/login');
    cy.get('[data-test="login-submit"]').click();
    cy.url().should('eq', 'https://practicesoftwaretesting.com/auth/login');
    cy.get('#email').should('be.visible');
    cy.get('#password').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Login Form Tests', () => {
  test('should log in successfully with valid credentials', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/auth/login');
    await page.fill('#email', 'test@example.com');
    await page.fill('#password', 'password123');
    await page.click('[data-test="login-submit"]');
    await expect(page).not.toHaveURL('https://practicesoftwaretesting.com/auth/login');
  });

  test('should not log in with empty fields', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/auth/login');
    await page.click('[data-test="login-submit"]');
    await expect(page).toHaveURL('https://practicesoftwaretesting.com/auth/login');
    await expect(page.locator('#email')).toBeVisible();
    await expect(page.locator('#password')).toBeVisible();
  });
});
